 const svg=base('#inventory'),x=d3.scaleLinear().domain([0,11]).range([55,1050]),y=d3.scaleLinear().domain([0,Math.max(1,d3.max(r.stockSeries),d3.max(noPurchases.stockSeries))*1.18]).nice().range([225,20]);svg.append('g').attr('transform','translate(55,0)').call(d3.axisLeft(y).ticks(4).tickSize(-995));svg.append('g').attr('transform','translate(0,225)').call(d3.axisBottom(x).ticks(12).tickFormat(h=>'S'+(h+1)));svg.append('path').datum(r.ledger).attr('d',d3.area().x(d=>x(d.h)).y0(225).y1(d=>y(d.closing)).curve(d3.curveStepAfter)).attr('fill','#edf0ff');[{vals:noPurchases.stockSeries,color:'#e98239',dash:'4 4'},{vals:r.stockSeries,color:'#4c57ff',dash:null}].forEach(z=>svg.append('path').datum(z.vals).attr('d',d3.line().x((d,h)=>x(h)).y(d=>y(d)).curve(d3.curveStepAfter)).attr('fill','none').attr('stroke',z.color).attr('stroke-width',2).attr('stroke-dasharray',z.dash));
 svg.selectAll('.arr').data(r.ledger.filter(d=>d.receipts+d.existing>0)).join('path').attr('d',d3.symbol().type(d3.symbolTriangle).size(70)()).attr('transform',d=>`translate(${x(d.h)},${y(d.closing)-12}) rotate(180)`).attr('fill','#408e7a').on('pointermove',(e,d)=>tip(e,`<b>Recepción S${d.h+1}</b>${num(d.existing)} u. de órdenes existentes<br>${num(d.receipts)} u. de nuevas compras<br>Cierre: ${num(d.closing)} u.`)).on('pointerleave',hide);
