function choose(id){sku=id;$('#sku').value=id;forecast();heat();warehouse();detail();catalog();advanced();if(currentView==="summary")switchView("demand")}
function render(){approved=false;$('#receipt').hidden=true;result=simulate(true);$('#approve').disabled=result.orders.length===0;const baseline=simulate(false);$('#budgetLabel').textContent=money(params().budget);$('#demand').textContent=num(result.demand);$('#spend').textContent=money(result.spend);$('#budgetGuide').textContent=`Referencia material aproximada: ${money(budgetReference)} = demanda base a costo − existencias y tránsito a costo. No incluye colchones ni empaques; no garantiza servicio por las fechas de llegada.`;$('#spendNote').textContent=`${result.orders.length} órdenes · ${money(params().budget-result.spend)} disponibles`;$('#lost').textContent=num(result.lost);$('#service').textContent=((1-result.lost/result.demand)*100).toFixed(1)+'%';const first=result.rows.filter(r=>r.lost.some(v=>v>0)).sort((a,b)=>a.lost.findIndex(v=>v>0)-b.lost.findIndex(v=>v>0))[0];$('#insight').innerHTML=`<div class="insightnumber">${num(baseline.lost-result.lost)}</div><p>unidades adicionales atendidas frente a no emitir nuevas compras.</p><div class="insightline">${first?`Primera alerta: <b>${first.name}</b>, semana ${first.lost.findIndex(v=>v>0)+1}.`:'El plan cubre toda la demanda esperada del horizonte.'}</div><div class="insightline">${params().delay?'<b>+2 semanas</b> de plazo en todos los proveedores.':'Plazos de proveedor: <b>2–5 semanas</b>.'}</div><div class="insightline">Las compras emitidas hoy no recuperan ventas perdidas antes de su llegada.</div>`;$('#orders').innerHTML=result.orders.map(o=>`<tr><td>${o.name}</td><td>S${o.placed+1}</td><td>S${o.week+1}${o.week>=12?' · fuera de horizonte':''}</td><td>${num(o.qty)}</td><td>${money(o.cost)}</td><td>Cobertura bajo objetivo</td></tr>`).join('')||'<tr><td colspan="6">No hay compras factibles con este presupuesto.</td></tr>';$('#audit').textContent=`Compras: ${money(result.spend)} ≤ ${money(params().budget)}. Demanda: ${num(result.demand)} = atendida ${num(result.demand-result.lost)} + perdida ${num(result.lost)}. Cantidades en múltiplos de empaque.`;forecast();heat();timeline();warehouse();detail();catalog();advanced()}
