function abcChart(){const svg=base('#abcPlot'),rows=D.products.map(p=>({...p,revenue:d3.sum(p.sales.slice(-52))*p.price})),x=d3.scaleLinear().domain([0,d3.max(rows,d=>d.revenue)*1.08]).range([70,625]),y=d3.scaleLinear().domain([0,d3.max(rows,d=>d.cv)*1.2]).range([275,25]),radius=d3.scaleSqrt().domain(d3.extent(rows,d=>d3.sum(d.forecast))).range([4,11]),col={A:'#4c57ff',B:'#a36bd3',C:'#e98239'};svg.append('g').attr('transform','translate(0,275)').call(d3.axisBottom(x).ticks(5).tickFormat(v=>(v/1000).toFixed(0)+'k'));svg.append('g').attr('transform','translate(70,0)').call(d3.axisLeft(y).ticks(4).tickFormat(v=>v.toFixed(2)));svg.append('text').attr('x',335).attr('y',319).attr('text-anchor','middle').attr('font-size',10).attr('fill','#75829b').text('Ingreso anual histórico sintético · MXN');svg.append('text').attr('x',70).attr('y',13).attr('font-size',10).attr('fill','#75829b').text('Variabilidad = desviación / media');svg.selectAll('.abc-point').data(rows).join('circle').attr('cx',d=>x(d.revenue)).attr('cy',d=>y(d.cv)).attr('r',d=>radius(d3.sum(d.forecast))).attr('fill',d=>col[d.abc]).attr('fill-opacity',.65).attr('stroke',d=>d.sku===sku?'#303c54':'white').attr('stroke-width',d=>d.sku===sku?2:1).attr('tabindex',0).attr('role','button').attr('aria-label',d=>d.name+' ABC '+d.abc).style('cursor','pointer').on('click',(e,d)=>choose(d.sku)).on('keydown',(e,d)=>{if(e.key==='Enter')choose(d.sku)}).on('pointermove',(e,d)=>tip(e,`<b>${d.name} · ${d.abc}</b>Ingreso ${money(d.revenue)}<br>Variabilidad ${d.cv}`)).on('pointerleave',hide);['A','B','C'].forEach((k,i)=>{svg.append('circle').attr('cx',480+i*48).attr('cy',12).attr('r',4).attr('fill',col[k]);svg.append('text').attr('x',488+i*48).attr('y',15).attr('font-size',10).attr('fill','#75829b').text(k)})}
function policyChart(){const svg=base('#frontier'),policies=[{name:'Servicio',buffer:1.65,c:'#4c57ff'},{name:'Equilibrio',buffer:1,c:'#a36bd3'},{name:'Efectivo',buffer:.5,c:'#e98239'}],rows=[];policies.forEach(p=>[.5,.75,1,1.25,1.5].forEach(f=>{const r=simulate(true,{budget:Math.round(params().budget*f),buffer:p.buffer});rows.push({...p,budget:Math.round(params().budget*f),spend:r.spend,service:(1-r.lost/r.demand)*100,lost:r.lost})}));rows.forEach(d=>d.dominated=rows.some(o=>o.spend<=d.spend&&o.service>=d.service&&(o.spend<d.spend||o.service>d.service)));const x=d3.scaleLinear().domain([0,d3.max(rows,d=>d.spend)*1.08]).range([60,625]),y=d3.scaleLinear().domain([Math.max(0,d3.min(rows,d=>d.service)-3),100]).range([275,30]);svg.append('g').attr('transform','translate(0,275)').call(d3.axisBottom(x).ticks(5).tickFormat(v=>(v/1e6).toFixed(1)+' M'));svg.append('g').attr('transform','translate(60,0)').call(d3.axisLeft(y).ticks(5).tickFormat(v=>v.toFixed(0)+'%'));svg.append('text').attr('x',335).attr('y',319).attr('text-anchor','middle').attr('font-size',10).attr('fill','#75829b').text('Importe de compras · MXN');policies.forEach((p,i)=>{const pts=rows.filter(d=>d.name===p.name);svg.append('path').datum(pts).attr('d',d3.line().x(d=>x(d.spend)).y(d=>y(d.service))).attr('fill','none').attr('stroke',p.c).attr('stroke-opacity',.5);svg.append('text').attr('x',70+i*170).attr('y',13).attr('font-size',10).attr('fill',p.c).text('● '+p.name)});svg.selectAll('.policy-point').data(rows).join('circle').attr('cx',d=>x(d.spend)).attr('cy',d=>y(d.service)).attr('r',5).attr('fill',d=>d.c).attr('opacity',d=>d.dominated?.25:1).attr('stroke','white').attr('tabindex',0).attr('role','img').attr('aria-label',d=>`${d.name}: compra ${money(d.spend)}, servicio ${d.service.toFixed(1)}%, ${d.dominated?'alternativa dominada':'no dominada entre las evaluadas'}`).on('pointermove',(e,d)=>tip(e,`<b>${d.name}${d.dominated?" · dominada":" · no dominada"}</b>Presupuesto ${money(d.budget)}<br>Compra ${money(d.spend)}<br>Servicio ${d.service.toFixed(1)}% · faltante ${num(d.lost)} u.`)).on('pointerleave',hide);const actual=(1-result.lost/result.demand)*100;svg.append('circle').attr('cx',x(result.spend)).attr('cy',y(actual)).attr('r',9).attr('fill','none').attr('stroke','#303c54').attr('stroke-width',1.4);svg.append('text').attr('x',Math.min(550,x(result.spend)+12)).attr('y',y(actual)-12).attr('font-size',10).attr('fill','#303c54').text('Plan actual');}
function waterfall(){const r=result.rows.find(r=>r.sku===sku),calc=r.calculations.find(c=>c.qty>0)||r.calculations[0],svg=base('#waterfall');if(!calc)return;const steps=[{label:'Demanda desde llegada',a:0,b:calc.cover},{label:'Colchón',a:calc.cover,b:calc.target},{label:'Disponible al recibir',a:calc.target,b:calc.target-calc.position},{label:'Necesidad neta',a:0,b:calc.raw},{label:'Empaque',a:0,b:calc.rounded},{label:'Compra financiada',a:0,b:calc.qty}];const x=d3.scaleBand().domain(d3.range(6)).range([55,1070]).padding(.3),y=d3.scaleLinear().domain([Math.min(0,calc.target-calc.position),Math.max(calc.target,calc.position,calc.rounded)*1.16]).nice().range([175,20]);svg.append('g').attr('transform','translate(45,0)').call(d3.axisLeft(y).ticks(4));svg.append('line').attr('x1',50).attr('x2',1080).attr('y1',y(0)).attr('y2',y(0)).attr('stroke','#d4dced');steps.forEach((s,i)=>{svg.append('rect').attr('x',x(i)).attr('y',y(Math.max(s.a,s.b))).attr('width',x.bandwidth()).attr('height',Math.max(1,Math.abs(y(s.a)-y(s.b)))).attr('fill',i===2?'#e98239':i===5?'#408e7a':'#777fff').attr('rx',3);svg.append('text').attr('x',x(i)+x.bandwidth()/2).attr('y',y(Math.max(s.a,s.b))-7).attr('text-anchor','middle').attr('font-size',11).attr('fill','#64738e').text(num(i===2?-calc.position:s.b-s.a));svg.append('text').attr('x',x(i)+x.bandwidth()/2).attr('y',205).attr('text-anchor','middle').attr('font-size',10).attr('fill','#64738e').text(s.label)})}
function stressChart(){let seed=37;const rand=()=>{seed=(1664525*seed+1013904223)>>>0;return seed/4294967296};const results=[];for(let n=0;n<120;n++){let demand=0,lost=0;for(const r of result.rows){let stock=r.stock;const draws=r.calibration_errors||[0],arrivals=[{week:r.inbound.week+params().delay,qty:r.inbound.qty},...r.orders.map(o=>({week:o.week,qty:o.qty}))].map(o=>{const u=rand();return{...o,week:o.week+(u<.7?0:u<.9?1:2)}});for(let h=0;h<12;h++){stock+=d3.sum(arrivals.filter(a=>a.week===h),a=>a.qty);const units=Math.max(0,Math.round(r.dem[h]*(1+draws[Math.floor(rand()*draws.length)])));demand+=units;lost+=Math.max(0,units-stock);stock=Math.max(0,stock-units)}}results.push({lost,service:(1-lost/demand)*100})}const vals=results.map(d=>d.lost).sort(d3.ascending),services=results.map(d=>d.service).sort(d3.ascending);$('#stressSummary').textContent=`Ventas sin cubrir: mediana ${num(d3.quantile(vals,.5))} u. · P90 ${num(d3.quantile(vals,.9))} u. | Servicio P10–P90 : ${d3.quantile(services,.1).toFixed(1)}%–${d3.quantile(services,.9).toFixed(1)}%`.replace('Ventes sans couvrir','Ventas sin cubrir').replace('médiane','mediana').replace('Service','Servicio');const svg=base('#stress'),x=d3.scaleLinear().domain([d3.min(vals)*.95,d3.max(vals)*1.05+1]).range([60,1060]),bins=d3.bin().domain(x.domain()).thresholds(16)(vals),y=d3.scaleLinear().domain([0,d3.max(bins,b=>b.length)*1.15]).nice().range([210,20]);svg.append('g').attr('transform','translate(0,210)').call(d3.axisBottom(x).ticks(8));svg.append('g').attr('transform','translate(60,0)').call(d3.axisLeft(y).ticks(4));svg.selectAll('.hist').data(bins).join('rect').attr('x',d=>x(d.x0)+1).attr('y',d=>y(d.length)).attr('width',d=>Math.max(0,x(d.x1)-x(d.x0)-2)).attr('height',d=>210-y(d.length)).attr('rx',3).attr('fill','#a5adff').on('pointermove',(e,d)=>tip(e,`<b>${num(d.x0)}–${num(d.x1)} unidades sin cubrir</b>${d.length} de 120 simulaciones`)).on('pointerleave',hide);svg.append('text').attr('x',65).attr('y',12).attr('font-size',10).attr('fill','#75829b').text('Número de escenarios');svg.append('text').attr('x',560).attr('y',250).attr('text-anchor','middle').attr('font-size',10).attr('fill','#75829b').text('Unidades de ventas no cubiertas · plan fijo')}
