const screenText={summary:['Qué atender primero.','Resumen global de los 48 SKU. El catálogo filtra la exploración; la asignación de presupuesto conserva su alcance global.'],demand:['Qué vender y cuánto confiar.','Pronóstico del producto seleccionado, referencia estacional e incertidumbre. Selecciona otro SKU sin perder escenario.'],inventory:['Dónde y cuándo falta inventario.','Balance del SKU seleccionado y cobertura del catálogo explorado. Las recepciones se contabilizan al inicio de cada semana.'],purchases:['Cuánto comprar y cuándo recibirlo.','Necesidad neta, empaque y presupuesto. Solo se emiten nuevas compras que llegan dentro de las 12 semanas.'],models:['Evidencia antes de decidir.','Comparación temporal de cuatro modelos. La prueba pública en USD queda separada del catálogo sintético en unidades.']};
function updateContext(){if(!result)return;const p=D.products.find(p=>p.sku===sku),t=screenText[currentView];$('#screenTitle').textContent=t[0];$('#screenContext').textContent=t[1];$('#screenScope').textContent=currentView==='models'?($('#evalDataset').value==='public'?'BENCHMARK PÚBLICO HISTÓRICO · USD · SIN INVENTARIO':'EVALUACIÓN DEL CATÁLOGO SINTÉTICO · UNIDADES'):'OPERACIÓN SIMULADA · 48 SKU · HORIZONTE 12 SEMANAS';$('#selectionContext').textContent=currentView==='models'?'Selección por validación · test posterior':p.sku+' · '+p.name;if(currentView==='inventory'||currentView==='purchases'){const rows=catalogRows(),inside=rows.some(r=>r.sku===sku);$('#screenContext').textContent+=` Alcance de cobertura: ${rows.length} SKU filtrados. ${inside?'':'El SKU seleccionado está fuera de ese filtro; su detalle sigue visible.'}`;}}
function switchView(view,writeHash=true){if(!Object.prototype.hasOwnProperty.call(screenText,view))view='summary';currentView=view;document.querySelectorAll('.screen').forEach(el=>el.hidden=el.id!=='screen-'+view);document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1});$('.controlbar').hidden=view==='models';$('.kpis').hidden=view==='models';$('#approve').hidden=view!=='purchases';$('#receipt').hidden=!approved||view!=='purchases';hide();updateContext();if(writeHash&&window.history?.replaceState){window.history.replaceState(null,'','#/'+view);$('.screencontext').scrollIntoView?.({block:'start',behavior:'instant'})}}
document.querySelectorAll('[data-view]').forEach(b=>{b.onclick=()=>switchView(b.dataset.view);b.onkeydown=e=>{const buttons=[...document.querySelectorAll('[data-view]')],i=buttons.indexOf(b);let next;if(e.key==='ArrowRight')next=(i+1)%buttons.length;if(e.key==='ArrowLeft')next=(i-1+buttons.length)%buttons.length;if(e.key==='Home')next=0;if(e.key==='End')next=buttons.length-1;if(next!==undefined){e.preventDefault();buttons[next].focus();switchView(buttons[next].dataset.view)}}});window.addEventListener('hashchange',()=>switchView(window.location.hash.replace('#/',''),false));
function executiveReview(){const risky=result.rows.filter(r=>d3.sum(r.lost)>0),exposed=d3.sum(result.rows,r=>d3.sum(r.lost)*r.price),closingValue=d3.sum(result.rows,r=>r.stockSeries.at(-1)*r.cost),overstock=result.rows.filter(r=>r.stockSeries.at(-1)>2*r.dem.at(-1)),urgent=result.orders.filter(o=>o.placed===0);$('#healthMetrics').innerHTML=`<div><small>PRODUCTOS CON FALTANTES</small><b>${risky.length} / 48</b><span>Demanda esperada sin atender en alguna semana</span></div><div><small>INGRESO POTENCIAL EXPUESTO</small><b>${money(exposed)}</b><span>Faltantes × precio simulado; antes de gastos</span></div><div><small>INVENTARIO AL CIERRE · COSTO</small><b>${money(closingValue)}</b><span>${overstock.length} SKU superan 2× demanda de S12</span></div><div><small>ÓRDENES A EMITIR EN S1</small><b>${urgent.length}</b><span>${money(d3.sum(urgent,o=>o.cost))} · al cierre de S1</span></div>`;const rows=[...result.rows].sort((a,b)=>d3.sum(b.lost)*b.price-d3.sum(a.lost)*a.price).slice(0,8),svg=base('#riskRanking'),x=d3.scaleLinear().domain([0,Math.max(1,d3.max(rows,r=>d3.sum(r.lost)*r.price))]).range([170,510]),y=d3.scaleBand().domain(rows.map(r=>r.sku)).range([20,325]).padding(.46);rows.forEach(r=>{const value=d3.sum(r.lost)*r.price,yy=y(r.sku)+y.bandwidth()/2,g=svg.append('g').attr('role','button').attr('tabindex',0).attr('aria-label',r.name+' exposición '+money(value)).style('cursor','pointer').on('click',()=>{choose(r.sku);switchView('inventory')}).on('keydown',e=>{if(e.key==='Enter'){choose(r.sku);switchView('inventory')}});g.append('text').attr('x',0).attr('y',yy+3).attr('font-size',10).attr('fill','#596984').text(r.name);g.append('line').attr('x1',170).attr('x2',x(value)).attr('y1',yy).attr('y2',yy).attr('stroke','#f1d5be').attr('stroke-width',3);g.append('circle').attr('cx',x(value)).attr('cy',yy).attr('r',4).attr('fill','#e98239');g.append('text').attr('x',x(value)+9).attr('y',yy+3).attr('font-size',9).attr('fill','#7a6b60').text(money(value))});$('#priorityNote').textContent='Orden por ingreso potencial expuesto, no por retorno causal. La primera recepción no recupera ventas perdidas antes de su llegada.'}
document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{scene=b.dataset.scene;document.querySelectorAll('[data-scene]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#sceneSelect').onchange=()=>{scene=$('#sceneSelect').value;render()};$('#baselineToggle').onchange=forecast;$('#sku').onchange=()=>choose($('#sku').value);$('#policy').onchange=render;$('#budget').oninput=render;$('#before').onclick=()=>{planned=false;$('#before').classList.add('active');$('#after').classList.remove('active');heat()};$('#after').onclick=()=>{planned=true;$('#after').classList.add('active');$('#before').classList.remove('active');heat()};$('#evidence').onclick=()=>{switchView('models');$('#method').open=true};$('#approve').onclick=()=>{approved=true;$('#receipt').hidden=false;$('#receipt').textContent=`Plan aprobado en esta sesión: ${result.orders.length} órdenes · ${money(result.spend)}. Recibo local; no se envían órdenes a proveedores.`};$('#download').onclick=()=>{const csv='SKU,Producto,Semana_emision,Semana_recepcion,Unidades,Importe_MXN\n'+result.orders.map(o=>[o.sku,o.name,o.placed+1,o.week+1,o.qty,o.cost].join(',')).join('\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='dockmind_compras_'+scene+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#evalDataset').onchange=()=>{evaluateModels();updateContext()};['#searchProduct','#categoryFilter','#channelFilter','#abcFilter','#sortCatalog'].forEach(id=>$(id).addEventListener(id==='#searchProduct'?'input':'change',refreshCatalog));render();switchView(window.location.hash.replace("#/",""),false);

window.__llmEstado = () => {
  const p = D.products.find((x) => x.sku === sku);
  if (!p || !result) return null;
  const ordenes = (result.orders || []).filter((o) => o.sku === sku);
  const totalUnidades = ordenes.reduce((a, o) => a + o.qty, 0);
  return {
    escenario: { id: String(scene), nombre: String(($('#sceneSelect') && $('#sceneSelect').selectedOptions[0] ? $('#sceneSelect').selectedOptions[0].textContent : scene)), parametros: { promo: params().promo ? 1 : 0, delay_dias: params().delay, buffer: params().buffer, presupuesto: params().budget } },
    sku: { sku: String(p.sku), nombre: String(p.name || ''), categoria: String(p.category || ''), lead: Number(p.lead) || 0, pack: Math.max(1, Number(p.pack) || 1), stock: Math.max(0, Number(p.stock) || 0), precio: Math.max(0, Number(p.price) || 0), costo: Math.max(0, Number(p.cost) || 0) },
    pronostico: { metodo: 'ensamble local', wape: Math.min(5, Math.max(0, Number(p.wape) || 0)), mae: Math.min(1000000, Math.max(0, Number(p.mae) || 0)), horizonte: (p.forecast || []).length },
    plan_compra: ordenes.slice(0, 26).map((o) => ({ semana: Number(o.week) || 0, cantidad: Number(o.qty) || 0, costo: Math.max(0, Number(o.cost) || 0) })),
    restricciones: { presupuesto: Math.max(0, Number(params().budget) || 0), buffer_dias: Math.max(0, Math.round(Number(params().buffer) || 0)) },
    metricas: { valores: {
      stock_unidades: Math.max(0, Number(p.stock) || 0),
      lead_dias: Math.max(0, Number(p.lead) || 0),
      pack: Math.max(1, Number(p.pack) || 1),
      compra_unidades: totalUnidades,
      compra_costo: Math.max(0, Number(result.spend) || 0),
      demanda_horizonte: Math.max(0, Number(result.demand) || 0)
    } }
  };
};
window.__llmDisponible = () => true;

